    @GetMapping("/public/linh-vuc-by-don-vi")
    public ResponseEntity<List<LinhVucDto>> getLinhVucByDonVi(@RequestParam Integer maDonVi) {
        List<LinhVucTuVan> list = catalogService.getActiveLinhVucByDonVi(maDonVi);
        List<LinhVucDto> dtos = list.stream().map(l -> new LinhVucDto(l.getMaLinhVuc(), l.getTenLinhVuc())).toList();
        return ResponseEntity.ok(dtos);
    }

    @GetMapping("/notifications/unread-count")
    public ResponseEntity<Long> getUnreadCount(@AuthenticationPrincipal CustomUserDetails userDetails) {
        if (userDetails == null) return ResponseEntity.ok(0L);
        return ResponseEntity.ok(notificationService.getUnreadCount(userDetails.getMaTK()));
    }

    @PostMapping("/notifications/{id}/read")
    public ResponseEntity<Void> markNotificationRead(@PathVariable Long id,
                                                     @AuthenticationPrincipal CustomUserDetails userDetails) {
        if (userDetails == null) return ResponseEntity.status(401).build();
        notificationService.markAsRead(id, userDetails.getMaTK());
        return ResponseEntity.ok().build();
    }

